input.command:
cd /tmp && : > exp.txt && for i in $(seq 0 255); do
case $i in
  9) v='\t';; 10) v='\n';; 13) v='\r';; 92) v='\\\\';;
  39) v="__SQ__";;
  *) if [ $i -ge 32 ] && [ $i -le 126 ]; then v=$(printf "\\$(printf '%03o' $i)"); else v=$(printf '\\x%02x' $i); fi;;
esac
if [ "$v" = "__SQ__" ]; then printf '%3d\tb"%s"\n' "$i" "'" >> exp.txt; else printf '%3d\tb'"'"'%b'"'"'\n' "$i" "$v" >> exp.txt; fi
done; diff exp.txt bytes.txt && echo "MODEL_MATCHES_ALL_256"

cd /tmp && node -e '
const out=[];
for(let i=0;i<256;i++){
  let body, q="'";
  if(i===9) body="\\\\t"; else if(i===10) body="\\\\n"; else if(i===13) body="\\\\r";
  else if(i===92) body="\\\\\\\\";
  else if(i===39){ q="\""; body="'"; }
  else if(i>=0x20&&i<0x7f) body=String.fromCharCode(i);
  else body="\\\\x"+i.toString(16).padStart(2,"0");
  out.push(String(i).padStart(3," ")+"\t"+"b"+q+body+q);
}
process.stdout.write(out.join("\n")+"\n");
' > exp2.txt; diff exp2.txt bytes.txt && echo "MODEL_MATCHES_ALL_256"

cat > /tmp/gen.mjs <<'EOF'
const SQ = String.fromCharCode(39), DQ = '"', BS = String.fromCharCode(92);
const out = [];
for (let i = 0; i < 256; i++) {
  let body, q = SQ;
  if (i === 9) body = BS + 't';
  else if (i === 10) body = BS + 'n';
  else if (i === 13) body = BS + 'r';
  else if (i === 92) body = BS + BS;
  else if (i === 39) { q = DQ; body = SQ; }
  else if (i >= 0x20 && i < 0x7f) body = String.fromCharCode(i);
  else body = BS + 'x' + i.toString(16).padStart(2, '0');
  out.push(String(i).padStart(3, ' ') + '\t' + 'b' + q + body + q);
}
process.stdout.write(out.join('\n') + '\n');
EOF
node /tmp/gen.mjs > /tmp/exp2.txt && diff /tmp/exp2.txt /tmp/bytes.txt && echo "MODEL_MATCHES_ALL_256"

cat > /tmp/diff.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
const SQ = String.fromCharCode(39), DQ = '"', BS = String.fromCharCode(92);
function pyBytesRepr(bytes) {
  const hasSQ = bytes.includes(39), hasDQ = bytes.includes(34);
  const q = (hasSQ && !hasDQ) ? DQ : SQ;
  let s = 'b' + q;
  for (const c of bytes) {
    if (c === 39 && q === SQ) s += BS + SQ;
    else if (c === 34 && q === DQ) s += BS + DQ;
    else if (c === 92) s += BS + BS;
    else if (c === 9) s += BS + 't';
    else if (c === 10) s += BS + 'n';
    else if (c === 13) s += BS + 'r';
    else if (c < 0x20 || c >= 0x7f) s += BS + 'x' + c.toString(16).padStart(2, '0');
    else s += String.fromCharCode(c);
  }
  return s + q;
}
let fails = 0, n = 0;
const cases = [];
// deterministic-ish random ASCII (1..126) strings, biased toward specials
const specials = [39, 34, 92, 9, 10, 13, 7, 11, 12, 27, 1, 0x7f, 32, 97, 65, 48];
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
for (let t = 0; t < 60; t++) {
  const len = 1 + Math.floor(rnd() * 10);
  const arr = [];
  for (let i = 0; i < len; i++) {
    arr.push(rnd() < 0.65 ? specials[Math.floor(rnd() * specials.length)] : 1 + Math.floor(rnd() * 126));
  }
  cases.push(arr);
}
cases.push([]);
cases.push([39]); cases.push([34]); cases.push([39, 34]); cases.push([92, 39]);
for (const arr of cases) {
  const arg = arr.map(c => String.fromCharCode(c)).join('');
  const r = spawnSync('/workspace/dataset/test8_executable', ['--a', '1', '--b', '2', '--c', arg], { encoding: 'latin1' });
  const line3 = r.stdout.split('\n')[2];
  const exp = pyBytesRepr(arr);
  n++;
  if (line3 !== exp || r.status !== 0) {
    fails++;
    console.log('MISMATCH bytes=' + JSON.stringify(arr) + '\n  got=' + JSON.stringify(line3) + '\n  exp=' + JSON.stringify(exp) + ' status=' + r.status);
  }
}
console.log(`ran=${n} fails=${fails}`);
EOF
node /tmp/diff.mjs
